        except InvalidRequirement:
            continue
        if _normalized_package_name(requirement.name, "pypi") == wanted:
            return str(requirement.specifier) or "*"
    return None

def _version_recommendation(
    classification: str,
    counts: dict[str, int],
    version_status: dict[str, int],
    delta: dict[str, Any],
    compact_delta_groups: dict[str, list[dict[str, Any]]],
) -> str:
    packages = sorted({str(item.get("package", "unknown")) for item in delta.get(classification, [])})
    package_names = f" for {', '.join(packages[:4])}" if packages else ""
    context = package_record_context(compact_delta_groups, classification)
    if version_status.get("affected"):
        return (
            f"Potential security concern: {version_status['affected']} {classification} advisory record(s) "
            f"have a deterministic affected installed version{package_names} ({context}). "
            "Review the affected range and fixed-version guidance."
        )
    if version_status.get("unknown"):
        if classification == "introduced":
            return (
                f"Review recommended: {counts['introduced']} advisory record(s) are new{package_names}, "
                "but installed-version impact is unknown. Check the preserved OSV range evidence; "
                "do not treat unknown as not affected."
            )
        return (
            f"Review recommended: {counts['remaining']} advisory record(s) remain{package_names}, "
            "but installed-version impact is unknown. Inspect the range evidence; "
            "unknown is not evidence that the installed version is safe."
        )
    if classification == "introduced":
        return (
            f"OSV returned {counts['introduced']} new advisory record(s){package_names}, but deterministic range "
            "assessment says the installed versions are not affected. Review the advisory evidence and dependency "
            "change; this does not establish application compatibility."
        )
    return (
        f"OSV records remain{package_names}, but deterministic range assessment says the installed versions are "
        "not affected. Review any advisory data discrepancy and application compatibility."
    )

