def _compatibility_text(
    fixed: list[Any], constraints: list[dict[str, Any]], constraints_status: str,
) -> str:
    compatible, incompatible = [], []
    for candidate in fixed:
        evaluations = [poetry_constraint_allows(entry.get("constraint"), str(candidate)) for entry in constraints]
        if evaluations and all(evaluations) and constraints_status == "complete":
            compatible.append(str(candidate))
        elif any(evaluation is False for evaluation in evaluations):
            incompatible.append(str(candidate))
    if incompatible:
        parent_text = ", ".join(sorted({
            f"{entry.get('parent', 'parent package')} ({entry.get('constraint', 'constraint unavailable')})"
            for entry in constraints
            if any(not poetry_constraint_allows(entry.get("constraint"), value) for value in incompatible)
        }))
        return (
            f"; fixed candidate(s) {', '.join(incompatible)} conflict with recorded constraint(s) from {parent_text}; "
            "a parent or coordinated dependency upgrade is needed; no compatible coordinated version set is established by the available metadata; "
            "do not upgrade this package in isolation"
        )
    if compatible:
        return f"; candidate {', '.join(compatible)} satisfies recorded dependency constraints"
    return "; fixed-version compatibility with parent constraints is unknown, do not recommend an isolated upgrade"

